const listConversationReaders = `-- name: ListConversationReaders :many
SELECT DISTINCT u.id, rp.permission_key = 'conversations.read_all' AS reads_all FROM users u
JOIN user_roles ur ON ur.user_id = u.id
JOIN role_permissions rp ON rp.role_id = ur.role_id
WHERE u.status = 'active' AND rp.permission_key IN ('conversations.read', 'conversations.read_all')
`

type ListConversationReadersRow struct {
	ID       uuid.UUID
	ReadsAll bool
}

// Active users who can read conversations (escalation notices).
func (q *Queries) ListConversationReaders(ctx context.Context) ([]ListConversationReadersRow, error) {
	rows, err := q.db.Query(ctx, listConversationReaders)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListConversationReadersRow{}
	for rows.Next() {
		var i ListConversationReadersRow
		if err := rows.Scan(&i.ID, &i.ReadsAll); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

